# Builds index.html (the page GitHub Pages serves at the site root) from the prototype.
# The prototype file has no <!doctype>/<html>/<head> because the claude.ai artifact viewer
# adds them; a normal web server needs them, so this wraps the file in a full document.
# Run from the project folder after changing the prototype:
#   powershell -ExecutionPolicy Bypass -File tools\build-index.ps1
$root = Split-Path -Parent $PSScriptRoot
$src = [IO.File]::ReadAllText((Join-Path $root 'prototype\suspension-prototype.html'), [Text.Encoding]::UTF8)
$head = "<!doctype html>`n<!-- Generated by tools/build-index.ps1 from prototype/suspension-prototype.html. Edit that file, not this one. -->`n<html lang=`"en`">`n<head>`n<meta charset=`"utf-8`">`n<meta name=`"viewport`" content=`"width=device-width, initial-scale=1, viewport-fit=cover`">`n<meta name=`"description`" content=`"Open-source suspension geometry and kinematics in the browser: drag hardpoints, set design targets, check packaging and export to CAD.`">`n"
$out = $head + $src + "`n</html>`n"
[IO.File]::WriteAllText((Join-Path $root 'index.html'), $out, (New-Object Text.UTF8Encoding $false))
Write-Output "index.html written ($([math]::Round($out.Length / 1024)) KB)"
